svg.script:
/* API para la pagina web / base de datos
   - Cada lote tiene id "MANZANA-LOTE" (A-01, B-12, C-25) + data-manzana y data-lote.
   - Al hacer clic se emite el evento "lote:click" con { id, manzana, lote, elemento }.
   - MapaLotes.seleccionar("A-01") marca un lote por codigo; MapaLotes.limpiar() quita la marca. */
(function () {
  var svg = document.documentElement, activo = null;

  function seleccionar(id) {
    var el = svg.getElementById(id);
    if (!el || !el.classList.contains('lote')) return null;
    if (activo) activo.classList.remove('activo');
    activo = el; el.classList.add('activo');
    var detalle = { id: el.id, manzana: el.dataset.manzana, lote: Number(el.dataset.lote), elemento: el };
    svg.dispatchEvent(new CustomEvent('lote:click', { bubbles: true, detail: detalle }));
    if (window.parent !== window)
      window.parent.postMessage({ tipo: 'lote:click', id: detalle.id, manzana: detalle.manzana, lote: detalle.lote }, '*');
    return detalle;
  }
  function limpiar() { if (activo) activo.classList.remove('activo'); activo = null; }

  svg.querySelectorAll('.lote').forEach(function (el) {
    el.addEventListener('click', function () { seleccionar(el.id); });
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); seleccionar(el.id); }
    });
  });
  window.MapaLotes = { seleccionar: seleccionar, limpiar: limpiar };
})();
